'use strict';
const PROJECT_URL='https://groves-signal-night.kydmgmt.chatgpt.site/';
const CASHTAG='$kyd888';
const STORAGE_KEY='groves-memory-v1';
async function copyText(value){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(value);return true;}const field=document.createElement('textarea');field.value=value;field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();let ok=false;try{ok=document.execCommand('copy');}finally{field.remove();}return ok;}
const input=document.getElementById('memory-text');
if(input){
 const prompts=[...document.querySelectorAll('[data-prompt]')],label=document.getElementById('memory-prompt'),count=document.getElementById('memory-count'),status=document.getElementById('memory-status');
 function choosePrompt(p){label.textContent=p;prompts.forEach(b=>{const selected=b.dataset.prompt===p;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});}
 function storeDraft(){count.textContent=input.value.length+' / 500';try{localStorage.setItem(STORAGE_KEY,JSON.stringify({prompt:label.textContent,text:input.value}));}catch{}}
 try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));if(saved&&typeof saved.text==='string'){input.value=saved.text.slice(0,500);if(prompts.some(p=>p.dataset.prompt===saved.prompt))choosePrompt(saved.prompt);count.textContent=input.value.length+' / 500';}}catch{}
 prompts.forEach(b=>b.addEventListener('click',()=>{choosePrompt(b.dataset.prompt);storeDraft();}));input.addEventListener('input',()=>{storeDraft();status.textContent='';});
 function card(){return 'GROVES: Signal Night\n\n'+label.textContent+'\n\n'+input.value.trim()+'\n\nA personal memory card\n'+PROJECT_URL;}
 function valid(){if(input.value.trim())return true;status.textContent='Write a few words to make your card.';input.focus();return false;}
 document.getElementById('save-memory').addEventListener('click',()=>{if(!valid())return;const blob=new Blob([card()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='my-groves-memory.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);status.textContent='Your card is ready to save. It has not been sent to KYD.';});
 document.getElementById('share-memory').addEventListener('click',async()=>{if(!valid())return;try{if(navigator.share){await navigator.share({title:'My GROVES memory',text:card()});status.textContent='Sharing complete.';}else{status.textContent=await copyText(card())?'Card copied. Paste it wherever you want to share it.':'Could not copy. Use “Save my card” instead.';}}catch(e){status.textContent=e.name==='AbortError'?'Sharing cancelled. Your card stays here.':'Could not share. Use “Save my card” instead.';}});
 document.getElementById('clear-memory').addEventListener('click',()=>{input.value='';count.textContent='0 / 500';try{localStorage.removeItem(STORAGE_KEY);}catch{}status.textContent='Your writing has been cleared from this browser.';input.focus();});
 document.getElementById('copy-cashtag').addEventListener('click',async()=>{const status=document.getElementById('donation-status');try{status.textContent=await copyText(CASHTAG)?'Cashtag copied.':'Copy this Cashtag: '+CASHTAG;}catch{status.textContent='Copy this Cashtag: '+CASHTAG;}});
 document.getElementById('share-project').addEventListener('click',async()=>{const status=document.getElementById('share-status');try{if(navigator.share){await navigator.share({title:'GROVES: Signal Night',text:'Explore KYD’s immersive music project.',url:PROJECT_URL});status.textContent='Sharing complete.';}else{status.textContent=await copyText(PROJECT_URL)?'Project link copied.':'Project link: '+PROJECT_URL;}}catch(e){status.textContent=e.name==='AbortError'?'Sharing cancelled.':'Project link: '+PROJECT_URL;}});
}
const present=document.getElementById('present');
if(present){let wakeLock=null;present.addEventListener('click',async()=>{const status=document.getElementById('tablet-status');try{if(!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();if('wakeLock' in navigator)wakeLock=await navigator.wakeLock.request('screen');status.textContent=wakeLock?'Display ready. Screen will stay awake while this page is visible.':'Display ready. Set your tablet’s auto-lock to stay on during the event.';}catch{status.textContent='Set your tablet’s auto-lock to stay on during the event.';}});document.getElementById('copy-project').addEventListener('click',async()=>{try{document.getElementById('tablet-status').textContent=await copyText(PROJECT_URL)?'Project link copied.':'Use the address below the QR code.';}catch{document.getElementById('tablet-status').textContent='Use the address below the QR code.';}});}
